function UIFishPoolFishAltasInfoNode:FillSelf()
    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(self._vo.id)
    if goodsVo then
        CfUtils.FillText(self.TextTitle, goodsVo.name)
        CfUtils.FillImage(self.ImgFishIcon, goodsVo.photoPath)
        CfUtils.SetUISwitchImage(self.ImgRare1, goodsVo.quality)
        CfUtils.FillImage(self.ImgRareBg, GoodsUtils.GetFishBgByQualityType(goodsVo.quality, true))
        CfUtils.FillText(self.StatusGet.transform:Find("ScrollRectDetails/Layout/TextFishInfo"), goodsVo.desc)
    end
    local dojo = fishingComponent:GetFishCollectionDojoByFishId(self._vo.id)
    local isHaveRecord = false
    local isHaveMaxRecord = false

    if dojo then
        isHaveRecord = (checkNumber(dojo.num) ~= 0)
        isHaveMaxRecord = (checkNumber(dojo.recordPlayerId) ~= 0)

        CfUtils.FillText(self.TextDate, dojo.date)
        CfUtils.FillText(self.TextLength, (dojo.length / 100).."CM")
        CfUtils.FillText(self.TextNumber, "x"..dojo.num)
        CfUtils.FillText(self.TextLength2, (dojo.recordLength / 100).."CM")
        CfUtils.FillText(self.TextID, dojo.recordPlayerId)
        CfUtils.FillText(self.TextName, dojo.recordPlayerName)
        CfUtils.FillText(self.TextDateOther, dojo.recordDate)

        
        CfUtils.SetUISwitchImage(self.TextGrade, (dojo.rating))
        CfUtils.SetUISwitchImage(self.TextGrade2, (dojo.recordRating))

        CfUtils.SetUISwitchImage(self.ImgIconGrade, FishingUtils.GetFishRareNameByRare(dojo.rating) == "S" and 2 or 1)
        CfUtils.SetUISwitchImage(self.ImgIconGrade2, FishingUtils.GetFishRareNameByRare(dojo.recordRating) == "S" and 2 or 1)

        if self._commonPlayerHeadNodeScr then
            local avatar = (dojo.avatar or dojo.recordPlayerAvatar)
            local avatarFrame = (dojo.avatarFrame or dojo.recordPlayerAvatarFrame)
            self._commonPlayerHeadNodeScr:FreshAvatarFrame(avatar, avatarFrame)
        end

        KTool.SetActive(self.Fishking, checkNumber(self._vo.isKing) == 1)

        CfUtils.SetUISwitchParticleSystem(self.UIFX_Common_TitleCloudEffect.transform:Find("YanWu1"), goodsVo.quality)
        CfUtils.SetUISwitchParticleSystem(self.UIFX_Common_TitleCloudEffect.transform:Find("YanWu2"), goodsVo.quality)
        CfUtils.SetUISwitchParticleSystem(self.UIFX_Common_TitleCloudEffect.transform:Find("LiZi"), goodsVo.quality)
        CfUtils.SetUISwitchParticleSystem(self.UIFX_Common_TitleCloudEffect.transform:Find("YanWu3"), goodsVo.quality)
        CfUtils.SetUISwitchParticleSystem(self.UIFX_Common_TitleCloudEffect.transform:Find("YanWu4"), goodsVo.quality)
        CfUtils.SetUISwitchParticleSystem(self.UIFX_Common_TitleCloudEffect.transform:Find("YanWu5"), goodsVo.quality)
        CfUtils.SetUISwitchParticleSystem(self.UIFX_Common_TitleCloudEffect.transform:Find("YanWu6"), goodsVo.quality)
    end
    --local Gradient2 = self.ImgFishIcon.transform:GetComponent(typeof(Gradient2))
    if not isHaveRecord then
        --CfUtils.FillText(self.TextTitle, "???")
    end
    --Gradient2.enabled = not isHaveRecord
    KTool.SetActive(self.StatusNotGet, not isHaveRecord)
    KTool.SetActive(self.StatusGet, true)

    KTool.SetActive(self.StatusNoRecord, not isHaveMaxRecord)
    KTool.SetActive(self.StatusHighestRecord, isHaveMaxRecord)

    KTool.SetActive(self.StatusGet.transform:Find("ScrollRectDetails/Layout").transform:Find("Details"), isHaveRecord)
    KTool.SetActive(self.StatusGet.transform:Find("IconNode").transform:Find("TextGet"), isHaveRecord)


    local gradient = self.ImgFishIcon.gameObject:GetComponent(typeof(CS.UnityEngine.UI.Extensions.Gradient2))
    gradient.enabled = not isHaveRecord
end

